// Generated by scripts/generate-workflow-blueprints.ts (extra questions); edit the specs there and re-run rather than editing by hand.
import { o, s, type QuestionSet } from "@/lib/interview-questions";

const bank: QuestionSet = {
  subjective: [
    s(5, "Walk me through the architecture of this nightly ETL workflow from trigger to report.", "A Schedule Trigger fires nightly in the timezone set in workflow settings. A Postgres node reads the last successful watermark and subtracts a small overlap window. An HTTP Request node pulls changed records using built-in pagination, a request interval for rate limits, and Retry On Fail for transient errors. A JavaScript Code node flattens the pages, maps and casts fields, normalises timestamps to UTC, and adds a run_id and payload hash. An IF node sends invalid rows to a quarantine table. Loop Over Items batches the valid rows, and a Postgres node upserts each batch with ON CONFLICT. Counts go to a run log keyed by execution ID. Only after every batch succeeds do we post the Slack report and advance the watermark. Any failure starts the Error Trigger workflow."),
    s(5, "Why subtract an overlap window from the watermark, and how would you choose its size?", "Source systems often commit records with an updated_at slightly earlier than the moment they become visible to the API. Examples are long transactions, replication lag, or clock differences. If we query strictly after the last watermark, those records fall into a gap and are lost forever. The overlap re-reads a small slice of time we already loaded. That costs nothing for correctness, because the upsert is idempotent and only updates when the incoming record is newer. I would size the window from observed lag: measure how late records actually arrive, then add margin. A wider window is safer but re-fetches more rows each night. If lateness can be unbounded, the overlap alone is not enough, and I would add a periodic reconciliation run."),
    s(5, "How do you handle records that are deleted in the source system?", "An updated_at incremental pull never sees hard deletes, because the row simply stops appearing. The best option is a source that exposes soft deletes, such as an is_deleted flag or a deleted_at timestamp that also bumps updated_at. The upsert then carries that flag into the warehouse. Some APIs offer a deleted-records or events endpoint, and we can pull it with its own cursor. If neither exists, I would schedule a periodic reconciliation. It fetches all primary keys from the source and compares them with the warehouse, then marks the missing ones deleted rather than removing them. That keeps history and makes the operation reversible. I would tell the interviewer this explicitly, because silent drift from deletes is a common gap in incremental ETL."),
    s(4, "Why is the watermark set to the highest source timestamp actually loaded rather than the time the run started?", "The run start time comes from the n8n server clock, while the cursor filters on the source system's timestamps. The two clocks can differ. A record stamped before our start time could also become visible after we fetched its page. Using now() could therefore skip records. The highest updated_at among rows we actually wrote is a fact about data we know is in the warehouse. If the API returned nothing, the watermark stays put. If some rows were quarantined, I would think about whether their timestamps should count. Usually they should, because quarantine holds them with a reason and a run_id. Combined with the overlap window, this keeps the cursor honest and only moving forward."),
    s(4, "Design the watermark table. What columns would you include and why?", "I would key it by pipeline name, so one table serves several syncs. Its columns would be: pipeline_name as the primary key; cursor_value, the timestamp or opaque API cursor; cursor_tiebreak_id, for composite cursors; last_success_execution_id; last_success_at; and updated_at. The advancing query should be conditional, for example updating only where the new value is greater than the stored one. That way a delayed or duplicate run can never move the cursor backwards. Storing the execution ID links the watermark to the run log and the n8n execution, which helps auditing. Some teams also keep a history table of every watermark change. That makes it easy to see exactly which windows were loaded and to roll back during an incident."),
    s(3, "What would your run log table look like, and how is it used?", "I would key it on the n8n execution ID, with pipeline name, run_id, status (running, succeeded or failed), started_at, finished_at, the window start and end, and counts for fetched, inserted, updated and rejected rows. It can also hold the failing node and error message, which the error workflow fills in. Each batch increments the counts, so a mid-run failure still shows how far the run got. The table drives the Slack report and gives operators history to compare nights. It also supports a freshness check: if no successful row appears within the expected window, something is wrong even though no error fired. Keying by execution ID lets you jump straight to the execution in n8n's log."),
    s(4, "How would you design the quarantine table and the process for reprocessing rejected rows?", "The quarantine table stores the raw source payload as JSONB, the source primary key if present, the rejection reason, the run_id, the execution ID, and timestamps for when the row was quarantined and when it was resolved. Storing the raw payload matters, because fixing a mapping bug later should not require re-fetching from the API. To reprocess, a separate manual or scheduled workflow reads unresolved rows. It runs them through the same transform and validation logic, ideally shared as a sub-workflow, and upserts the ones that now pass before marking them resolved. Because the main load is idempotent and only accepts newer records, replaying an old quarantined row cannot overwrite a fresher version already in the warehouse."),
    s(4, "What is the payload hash for, and how would you use it in the upsert?", "The hash is computed over the business fields after the transform, in a stable order, so identical content always gives the same value. It has two main uses. First, change detection: the ON CONFLICT update can require both a newer timestamp and a different hash. That skips no-op updates, which reduces write load and stops audit columns from churning when the overlap window re-reads unchanged rows. Second, diagnostics: when inserted and updated counts look odd, comparing hashes shows whether content really changed. It also helps reconciliation against the source. Exclude volatile fields like run_id from the hash, or every rerun will look like a change."),
    s(4, "How do you prevent two executions of this workflow from running at the same time, and why does it matter?", "A manual rerun could overlap with the scheduled run, or a slow night could still be running when someone retries. Overlapping runs duplicate API load and make run logs confusing. In the worst case, a slower run could try to move the watermark after a faster one. I would take a Postgres advisory lock, or claim a lock row for the pipeline, at the start of the workflow, and exit cleanly if it is already held. The lock must be released on both success and failure, so I would either give it a timeout or have the error workflow clear it. The conditional watermark update, which only moves forward, and the newer-only upsert are the safety net: even if two runs overlap, they cannot corrupt data."),
    s(4, "What pagination pitfalls would you watch for when pulling changed records?", "Offset pagination is the main risk. If records are updated while you page, rows shift between pages, so some get skipped and others duplicated. Cursor-based pagination, or keyset pagination on a stable sort such as updated_at then id, avoids that. Make sure the API sorts results deterministically. Ties on updated_at need a tiebreaker, or a page boundary can split records with the same timestamp. Configure the HTTP Request node's 'complete when' condition carefully, for example when the next cursor is empty or the response has no items. A wrong condition either stops early and loses data or loops forever. I would also set a maximum-requests guard, and log the page count to the run log."),
    s(3, "How would you tune the request interval and Retry On Fail settings for the source API?", "Start from the API's documented rate limit and set the pagination request interval so we stay comfortably below it, leaving headroom for other consumers of the same key. Retry On Fail should be enabled on the HTTP Request node with a few tries and a wait between them, so a brief 429 or 5xx is absorbed without failing the run. Respect Retry-After headers where the API provides them. Do not retry permanent errors such as 400, 401 or 404 blindly, because they will just fail again and waste time. If 429s still appear, increase the interval or reduce page concurrency rather than adding more retries. Retries also lengthen runtime, so check the run still fits its nightly window."),
    s(3, "How would you estimate how long a nightly run takes?", "I would build a simple model from measured inputs rather than guesses. Fetch time is roughly the number of changed records divided by page size, multiplied by the request interval plus average response time. As an illustration: if 200,000 records change, pages hold 100, and each request plus interval takes about one second, that is about 2,000 requests, or around 33 minutes. Add transform time, which is usually small. Add load time, which is the number of batches multiplied by the measured upsert time per batch. Then add margin for retries and the overlap window. I would compare the total with the nightly maintenance window and with the source's rate limit, and record actual durations in the run log to refine the model."),
    s(4, "A batch in the middle of the load fails. What state is the system in, and what happens next?", "Earlier batches are already committed, because each upsert statement is atomic for its batch. The failed batch either applied fully or not at all, depending on the Postgres node's query batching mode. Running it as a single query or inside a transaction keeps it atomic. The watermark has not moved, because that only happens after all batches succeed. The error workflow marks the run failed in the run log, records the failing node and message, and posts a Slack alert with the execution link. The next scheduled run or a manual rerun fetches the same window again. Already-loaded rows hit ON CONFLICT and are either skipped or updated only if they are newer, so nothing is duplicated and nothing is lost."),
    s(5, "This pipeline claims to never lose or duplicate rows. Is that exactly-once delivery?", "Not strictly. Fetching is at-least-once: the overlap window and reruns deliberately re-read records. What we achieve is effectively-once results in the warehouse. Each record lands exactly once, because the load is an idempotent upsert on the natural key with a newer-only condition. No loss comes from never advancing the watermark until the load succeeds, plus the overlap window for late arrivals. The guarantees have limits. Hard deletes are not seen without soft-delete flags or reconciliation. Records arriving later than the overlap window can be missed. A wrong natural key would merge distinct records. Being honest about these limits is usually what the interviewer wants."),
    s(3, "Why use a Code node for the transform instead of Set or Edit Fields nodes?", "The transform does several things at once: it flattens nested pages into one item per record, maps many fields, casts types, normalises timestamps to UTC, and computes a hash. In JavaScript that is compact, testable logic in one place. The same work spread across many Set nodes and expressions is harder to review and change. A Code node also lets us use deterministic hashing and consistent date parsing. The trade-offs are that it is less visual for non-developers and that bugs in custom code are our responsibility. For simple renames, Edit Fields is fine. I would keep the Code node focused, avoid side effects, and cover it with test fixtures."),
    s(3, "How do you deal with time zones in this workflow?", "There are two separate concerns. The Schedule Trigger fires according to the timezone in workflow settings, so set it explicitly. That keeps 'nightly' from drifting across daylight-saving changes or server defaults. Data timestamps are a different matter. The Code node parses every source timestamp, including any offset, and normalises it to UTC before loading into timestamptz columns. The watermark is stored in UTC too. Mixing a local-time watermark with UTC data is a classic way to skip or re-read hours of records. Reject unparseable or offset-less dates to quarantine rather than guessing, unless the source documents a fixed zone. The run report can show local times for humans, but the storage and comparison layers stay in UTC."),
    s(4, "How do you handle many records sharing the same updated_at value at a page or window boundary?", "If the cursor is only a timestamp and we query with greater-than, records with the same timestamp as the watermark that were not loaded yet get skipped. If we use greater-than-or-equal, we re-read them, which is safe because the upsert is idempotent. The overlap window already makes re-reads normal, so greater-than-or-equal plus the overlap is the simple, safe choice. For very high-volume sources, a composite cursor of (updated_at, id), with the API sorting by both, gives precise resumption without big overlaps. The watermark table can store both values. Whatever you choose, the API's sort order must match the cursor definition, or the boundary logic breaks."),
    s(3, "The source API adds or renames a field. How should the workflow respond?", "New fields are harmless if the Code node maps fields explicitly instead of passing everything through. They are simply ignored until we decide to add a warehouse column. A renamed or removed field is more dangerous, because the mapping produces nulls. Validation should catch required fields going missing, and the rejects land in quarantine with a clear reason. I would also set a threshold. If the reject rate spikes far above normal, fail the run deliberately so the watermark does not advance and a human looks at it. Keeping the raw payload in quarantine means we can fix the mapping and replay. Schema changes on the warehouse side should go through migrations, not ad hoc edits."),
    s(4, "Should a sudden spike in rejected rows fail the run, even though quarantine exists to prevent that?", "Quarantine exists so one bad record does not block the night. But if 40 percent of rows fail validation, the likely cause is a systemic problem such as an API change, an auth issue returning error bodies, or a mapping bug, not bad data. Loading the remainder and advancing the watermark would then hide a big data-quality incident. I would add a check after validation: if rejects exceed a configured percentage or count, throw an error. That triggers the error workflow and keeps the watermark in place, so a rerun covers the window after the fix. The threshold should come from normal historical reject rates in the run log, not a guess."),
    s(4, "What security measures would you apply to this workflow?", "The source API key and Postgres password live in n8n's encrypted credentials and are referenced by nodes, never hard-coded in Code nodes or expressions. The Postgres credential uses a least-privilege role: SELECT and UPDATE on the watermark table, INSERT and UPDATE on the target tables, the run log and quarantine, and no DDL or superuser rights. Use TLS for both the API and the database. Restrict who can edit the workflow and view executions in n8n, because execution data contains real records. Protect the instance's encryption key, and rotate credentials on a schedule. On self-hosted deployments, keep n8n patched and do not expose its editor publicly without authentication."),
    s(4, "Execution logs and Slack reports could expose personal data. How do you manage privacy?", "n8n can save execution data, and for this workflow that means real customer records sitting in its database. I would configure execution data saving so successful runs are not stored, or are pruned quickly, while failed runs are kept for a limited period for debugging. Access to executions should be limited to the team that owns the pipeline. The Slack report should carry only aggregates: counts, durations, window bounds, and the execution link. It should never include record contents or personal fields. Error messages can echo payloads, so the error workflow should truncate or sanitise them before posting. Quarantine holds raw payloads, so it needs the same access controls and retention policy as the warehouse table it feeds."),
    s(3, "How would you test this workflow before trusting it in production?", "First, unit-test the transform by pinning sample API responses on the HTTP node and running the Code and IF nodes against fixtures. Those fixtures should cover nulls, bad dates, odd time zones, duplicate keys and nested pages. Then run the whole flow against a staging schema with a non-production API key. Run it twice over the same window and confirm the row counts and hashes are identical, which proves idempotency. Kill it mid-load and rerun it to prove recovery. Note that error workflows do not fire on manual test executions, so test the Error Trigger path with an active scheduled or triggered run that fails on purpose. Finally, reconcile counts against the source for a known window."),
    s(4, "How would you detect a night when the workflow silently did not run at all?", "The error workflow only fires when an execution fails. If the instance was down, the workflow got deactivated, or the schedule never fired, nothing alerts. I would add a separate dead-man's-switch check. A small workflow, ideally running somewhere independent, queries the run log or watermark table each morning. It alerts if there is no successful run within the expected window or if the watermark has not advanced in too long. An external uptime or heartbeat monitor works too: the main workflow pings it on success, and the monitor alerts when pings stop. Freshness checks on the warehouse tables themselves are also useful for downstream consumers."),
    s(3, "How would you run a historical backfill with this same workflow?", "I would not edit the production watermark by hand. Instead, I would parameterise the window: a manual or sub-workflow entry point accepts a start and end, and the scheduled path reads them from the watermark table. The backfill runs the same fetch, transform, validate and upsert steps. Idempotent upserts mean it can safely overlap with data already loaded. I would chunk a long backfill into smaller date ranges so each execution stays small, and throttle it to respect the API's rate limits. It should also avoid running at the same time as the nightly job. The backfill should log to the run log with its own marker, and it should not advance the nightly watermark unless that is intended."),
    s(3, "When would you move this n8n instance to queue mode?", "In regular mode, one n8n process handles the editor, triggers and executions. A heavy nightly ETL can compete with other workflows for memory and CPU on that process. Queue mode uses Redis as a broker, with separate worker processes running executions, so heavy jobs are isolated and you can scale workers horizontally. I would move when several heavy workflows overlap, when executions queue behind each other, or when a single process becomes a reliability risk. Queue mode does not make one execution faster or lighter on memory. A single huge execution still needs splitting into sub-workflows. It also adds operational parts, Redis and the workers, that need monitoring."),
    s(3, "How could sub-workflows with Execute Workflow improve this design?", "Holding every page and record in a single execution keeps all those items in memory and makes the execution log huge. Instead, the parent workflow could compute the window, then call a sub-workflow per date slice or per group of pages. Each child fetches, transforms and upserts its slice and returns only counts. The parent aggregates the counts, posts the report and advances the watermark only if every child succeeded. Children release memory when they finish, failures are scoped to one slice, and the transform logic can be reused by the quarantine reprocessing and backfill workflows. The trade-off is more moving parts, plus care that a child failure propagates to the parent so the watermark does not move."),
    s(3, "If the Slack post fails, the watermark does not advance. Is that the right design?", "As written, yes: the report and the watermark are in sequence, so a Slack outage fails the run and keeps the cursor in place. That is safe, because the next run re-reads the window idempotently. But it is wasteful, and it creates a false 'failed' signal even though the data loaded fine. A reasonable alternative is to advance the watermark immediately after the last batch succeeds, then post the report with Continue On Fail or a short retry, so a notification failure cannot block progress. The key invariant is that the watermark moves only after a successful load. Notification delivery is secondary. I would discuss this trade-off openly with the interviewer."),
    s(3, "How do you choose between an updated_at timestamp cursor and an opaque API cursor?", "A timestamp cursor is transparent: we can subtract an overlap, inspect it and set it manually for backfills. It depends on the source updating the timestamp reliably and on consistent sorting. An opaque cursor or change token from the API can be more precise and can include deletes, but it cannot be adjusted with an overlap window. It may also expire if we do not use it within a retention period, which forces a full resync. If the API offers a change feed with a cursor, I would use it and store the token only after a successful load. Otherwise I would use updated_at with a tiebreaker. Either way, the watermark table stores whichever value we resume from."),
    s(2, "How would you pick the batch size for the Loop Over Items upsert?", "Batch size trades round trips against statement size and lock duration. Very small batches mean many queries and a slow load. Very large batches mean long transactions, more memory in n8n, and bigger rollbacks when one row hits a constraint error. I would start with a moderate size and measure the upsert time per batch in the run log. Then I would adjust while watching Postgres for lock waits and the n8n worker for memory. Also consider the parameter limits on a single statement when many columns are inserted per row. The right number depends on row width and indexes on the target table, so it should be configurable rather than hard-coded."),
    s(3, "What would you add to make the warehouse data trustworthy for downstream users beyond 'the job succeeded'?", "Success only means nothing crashed. I would add data-quality checks after the load. These include row-count reconciliation against the source for the window where the API exposes counts, checks that no natural keys are duplicated, null-rate checks on critical columns, and a freshness check on max(updated_at). Persist the results in the run log and include a summary in the Slack report. For important tables, a periodic full-key reconciliation catches deletes and late records that the incremental path misses. Document the table's freshness expectations, for example that it reflects source data up to the last watermark, so analysts know what 'current' means."),
  ],
  objective: [
    o(5, "Which node in this workflow follows next-page cursors or links using built-in pagination?", ["HTTP Request node","Loop Over Items node","Merge node","Wait node"], 0, "The HTTP Request node has built-in pagination options that follow next-page cursors or links until a 'complete when' condition is met."),
    o(4, "Where do you tell n8n which error workflow to run when this ETL workflow fails?", ["In the HTTP Request node's options","In the ETL workflow's settings","In the Postgres credential","In the Schedule Trigger's parameters"], 1, "The error workflow is selected in the failing workflow's settings. That error workflow starts from an Error Trigger node."),
    o(4, "Which information does the Error Trigger give the error workflow in this design?", ["Only a boolean failure flag","The full warehouse table contents","The workflow name, execution ID, failing node and error message","The source API credential in plain text"], 2, "The error workflow uses the workflow name, execution ID, last failing node and error message to mark the run failed and alert Slack with the execution link."),
    o(5, "Which Postgres statement makes the batch load idempotent while only applying newer records?", ["INSERT … VALUES with no conflict clause","DELETE all rows then INSERT","INSERT … ON CONFLICT (natural_key) DO UPDATE … WHERE excluded.updated_at > target.updated_at","TRUNCATE then COPY"], 2, "ON CONFLICT on the natural key turns duplicates into updates, and the WHERE condition prevents older data from overwriting newer rows."),
    o(4, "What must exist in Postgres for INSERT … ON CONFLICT (natural_key) to work?", ["A trigger on the table","A unique constraint or unique index on the conflict columns","A foreign key to the watermark table","A sequence on natural_key"], 1, "Postgres needs a unique constraint or unique index matching the conflict target to detect conflicts."),
    o(3, "In a Postgres ON CONFLICT DO UPDATE clause, what does EXCLUDED refer to?", ["Rows deleted earlier in the run","The row that was proposed for insertion","Rows rejected to quarantine","The previous version of the watermark"], 1, "EXCLUDED is the special table holding the incoming row that conflicted, so its values can be compared with or written to the existing row."),
    o(5, "Why does the workflow subtract a small overlap window from the stored watermark?", ["To reduce API calls","To catch late-arriving records that were committed with earlier timestamps","To make the Schedule Trigger fire earlier","To skip records already in quarantine"], 1, "The overlap re-reads a slice of time so records that became visible late are not missed. The idempotent upsert makes the re-read harmless."),
    o(5, "What is the main risk of advancing the watermark before the load finishes?", ["Duplicate rows in the warehouse","Permanent data loss if the load then fails","Slower Slack messages","Higher API rate limits"], 1, "If the cursor moves first and the load fails, the next run starts after records that were never loaded, so they are skipped."),
    o(4, "The watermark is advanced to which value?", ["The n8n server's current time","The time the Schedule Trigger fired","The highest source timestamp actually loaded","The time the Slack report was posted"], 2, "Using the highest loaded source timestamp avoids clock skew between systems and never claims data that was not written."),
    o(3, "Which setting determines the timezone the nightly Schedule Trigger uses?", ["The Postgres server timezone","The timezone set in workflow settings","The source API's timezone","UTC always, with no option to change it"], 1, "Per the design, the Schedule Trigger fires using the timezone configured in the workflow's settings."),
    o(4, "Which errors should Retry On Fail on the HTTP Request node mainly absorb here?", ["400 Bad Request","401 Unauthorized","Transient 429 and 5xx errors","Validation failures in the Code node"], 2, "Rate limits and server errors are usually temporary, so waiting and retrying helps. Client errors like 400 or 401 will fail again."),
    o(4, "What does the Loop Over Items node do in this workflow?", ["Paginates the source API","Splits valid rows into fixed-size batches for upserting","Waits for human approval","Merges valid and rejected rows"], 1, "Loop Over Items processes items in batches, so each Postgres upsert handles a fixed-size chunk."),
    o(4, "Why are invalid rows routed to a quarantine table instead of throwing an error?", ["So one bad record does not fail the whole night's load","Because Postgres cannot store invalid rows","To avoid writing a run log","Because the IF node cannot throw errors"], 0, "Quarantine records the reject with its reason and run_id so valid rows still load and bad ones can be fixed and replayed."),
    o(3, "What is a sensible use of the per-row payload hash?", ["Encrypting the row at rest","Skipping no-op updates when content has not changed","Replacing the natural key","Authenticating to the source API"], 1, "Comparing hashes in the upsert condition avoids rewriting identical rows that the overlap window re-reads."),
    o(4, "Why is offset-based pagination risky for pulling changed records?", ["It always returns empty pages","Rows can shift between pages as data changes, causing skips or duplicates","It cannot be used with credentials","It disables rate limiting"], 1, "When records are updated during paging, offsets move, so some rows are skipped and others appear twice. Cursor or keyset pagination is stable."),
    o(3, "Many records share the same updated_at at the watermark boundary. Which cursor design resumes precisely?", ["Page number only","A composite cursor of (updated_at, id) with matching sort order","The n8n execution ID","A random sample of IDs"], 1, "Adding a unique tiebreaker to the timestamp gives a strict ordering, so resuming neither skips nor endlessly repeats tied records."),
    o(5, "What delivery semantics does this pipeline actually provide?", ["Exactly-once fetching from the API","At-most-once fetching with no retries","At-least-once fetching made effectively-once by idempotent upserts","Best-effort with possible duplicates"], 2, "The overlap and reruns re-read data, which is at-least-once. Upserts on the natural key make the stored result effectively-once."),
    o(4, "Batch 7 of 20 fails after retries. Which statement is true?", ["All previous batches are rolled back automatically","The watermark advances to the end of batch 6","Batches 1–6 stay committed, the watermark is unchanged, and a rerun is safe","The rerun will duplicate batches 1–6"], 2, "Each batch commits independently and the cursor only moves after all batches succeed. Idempotent upserts make reprocessing batches 1–6 harmless."),
    o(3, "Why does the run log use the n8n execution ID as its key?", ["It is required by the Postgres node","It links counts and status directly to the logged n8n execution for debugging","It replaces the natural key","It encrypts the run data"], 1, "Keying by execution ID lets operators move from a run log row or Slack alert straight to the n8n execution that produced it."),
    o(4, "Does an n8n error workflow fire when you run the main workflow manually in the editor and it fails?", ["Yes, always","No, error workflows run for automatic executions, not manual test runs","Only if the Error Trigger is pinned","Only in queue mode"], 1, "n8n triggers error workflows for failed production (automatic) executions, so testing the alert path needs an active trigger that fails on purpose."),
    o(4, "An incremental pull on updated_at cannot see which type of change without extra work?", ["New inserts","Field updates","Hard deletes in the source","Type changes in a column"], 2, "A hard-deleted row simply stops appearing. You need soft-delete flags, a deletes endpoint or periodic key reconciliation."),
    o(3, "Why does the Code node normalise all timestamps to UTC?", ["Postgres cannot store other zones","So comparisons with the watermark are consistent and not distorted by offsets or daylight saving","To shorten the payload hash","Because Slack requires UTC"], 1, "Mixing zones causes the watermark comparison to skip or re-read hours of data. UTC gives a single consistent timeline."),
    o(4, "What is the best practice for the Postgres credential used by this workflow?", ["A superuser so migrations can run","A least-privilege role limited to the needed tables and operations","The same account used by analysts","A credential embedded in the Code node"], 1, "Least privilege limits damage from mistakes or a compromised instance. Credentials belong in n8n's encrypted credential store."),
    o(3, "How should the source API key be supplied to the HTTP Request node?", ["Hard-coded in a Code node","Through an n8n credential stored encrypted and referenced by the node","In the Slack report","As a query parameter in the workflow name"], 1, "n8n stores credentials encrypted and nodes reference them, which keeps secrets out of workflow JSON and execution logic."),
    o(3, "What does running n8n in queue mode require?", ["Kafka","Redis as a message broker plus worker processes","A second Postgres warehouse","n8n Cloud only"], 1, "Queue mode uses Redis to distribute executions to worker processes, which scales execution throughput."),
    o(3, "A single execution holding millions of items is running out of memory. Which change helps most directly?", ["Increase Retry On Fail attempts","Split the work into date or page slices processed by sub-workflows via Execute Workflow","Post more Slack messages","Remove the IF node"], 1, "Sub-workflows process smaller slices and release memory when they finish. Queue mode alone does not shrink a single execution."),
    o(3, "How can you detect a night when the workflow never ran at all?", ["The Error Trigger always fires for missed schedules","A separate freshness or heartbeat check on the run log or watermark","Retry On Fail on the Schedule Trigger","The Slack node's delivery receipt"], 1, "No execution means no error, so an independent dead-man's-switch check is needed to alert when successful runs stop."),
    o(3, "What is a safe way to stop a manual rerun from overlapping with the scheduled run?", ["Disable the upsert","Take a Postgres advisory lock or lock row at the start and exit if it is held","Delete the watermark before each run","Run without the error workflow"], 1, "A lock ensures only one run proceeds. The forward-only watermark update and idempotent upsert remain a safety net."),
    o(2, "Which languages can the n8n Code node use for the transform step?", ["Only SQL","JavaScript or Python","Only Go","Bash only"], 1, "The Code node supports JavaScript and Python. This design uses JavaScript."),
    o(3, "What should the nightly Slack run report contain to respect privacy?", ["Full records that failed validation","Aggregate counts, window bounds, status and the execution link","The database password for quick fixes","Raw API responses"], 1, "Aggregates give operators what they need without leaking personal data into a chat channel."),
  ],
};
export default bank;
